message.content:
{
  "episode_title": "The Inspector and the Impossible Ding",
  "logline": "Voss tries to document a code violation while Ellis and Mara struggle to hide the elevator's tendency to visit non-existent floors.",
  "tone": [
    "surreal",
    "comedy"
  ],
  "target_duration_seconds": 50.0,
  "active_characters": [
    "ellis",
    "mara",
    "voss"
  ],
  "primary_location": "floor_3_hallway",
  "central_goal": {
    "character": "mara",
    "goal": "complete the shift without revealing anomalies"
  },
  "beats": [
    {
      "id": "beat_1",
      "narrative_purpose": "Hook: The elevator dings and the lights flicker aggressively.",
      "target_start_second": 0.0,
      "actions": [
        {
          "actor": "ellis",
          "action": "look_at",
          "target": "floor_3_hallway"
        },
        {
          "actor": "ellis",
          "action": "speak",
          "text": "Did you hear that? It sounded like a choir of bells! A very loud, very angry choir!"
        },
        {
          "actor": "mara",
          "action": "flicker_lights",
          "target": "floor_3_hallway"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "It's just the wiring, Ellis. Old building. Very old. Probably just settling into the earth."
        }
      ],
      "camera_intent": {
        "type": "establish",
        "subject": "ellis"
      },
      "completion_condition": {
        "type": "dialogue_finished",
        "actor": "mara"
      }
    },
    {
      "id": "beat_2",
      "narrative_purpose": "Voss enters to inspect the hallway.",
      "target_start_second": 8.0,
      "actions": [
        {
          "actor": "voss",
          "action": "enter_room",
          "target": "floor_3_hallway"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "Superintendent Mara! I'm here for the quarterly audit. This hallway is a mess."
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "Why is the hallway light blinking in Morse code? Is the building trying to talk to me?"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "It's a feature! Energy saving! It's very modern, really. Don't mind the rhythm."
        }
      ],
      "camera_intent": {
        "type": "conversation",
        "subject": "voss"
      },
      "completion_condition": {
        "type": "dialogue_finished",
        "actor": "mara"
      }
    },
    {
      "id": "beat_3",
      "narrative_purpose": "Ellis tries to investigate the elevator.",
      "target_start_second": 16.0,
      "actions": [
        {
          "actor": "ellis",
          "action": "approach",
          "target": "floor_3_hallway"
        },
        {
          "actor": "ellis",
          "action": "speak",
          "text": "The elevator is opening! But there's nothing there! Just purple fog and the smell of ozone!"
        },
        {
          "actor": "voss",
          "action": "look_at",
          "target": "floor_3_hallway"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "Purple fog is not on the approved building materials list. This is highly irregular."
        }
      ],
      "camera_intent": {
        "type": "tension_push",
        "subject": "ellis"
      },
      "completion_condition": {
        "type": "dialogue_finished",
        "actor": "voss"
      }
    },
    {
      "id": "beat_4",
      "narrative_purpose": "Mara attempts to deflect the inspector.",
      "target_start_second": 25.0,
      "actions": [
        {
          "actor": "mara",
          "action": "move_to",
          "target": "voss"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "It's just... localized humidity. Very high, very purple humidity. It's a tropical microclimate!"
        },
        {
          "actor": "voss",
          "action": "inspect",
          "target": "floor_3_hallway"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "Humidity doesn't hum 'The Star-Spangled Banner' at forty decibels. Explain that, Mara."
        }
      ],
      "camera_intent": {
        "type": "over_the_shoulder",
        "subject": "mara",
        "reaction_subject": "voss"
      },
      "completion_condition": {
        "type": "dialogue_finished",
        "actor": "voss"
      }
    },
    {
      "id": "beat_5",
      "narrative_purpose": "Escalation: The elevator makes a loud noise.",
      "target_start_second": 34.0,
      "actions": [
        {
          "actor": "ellis",
          "action": "shout",
          "text": "It's pulling in a vacuum! My hair is standing up! Help!"
        },
        {
          "actor": "mara",
          "action": "activate",
          "target": "floor_3_hallway"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "Voss, please! Stop writing! I have a quota to meet and a reality to maintain!"
        },
        {
          "actor": "voss",
          "action": "write_note",
          "text": "Violation: Unsanctioned spatial rift and unauthorized musical humidity."
        }
      ],
      "camera_intent": {
        "type": "reaction",
        "subject": "voss"
      },
      "completion_condition": {
        "type": "dialogue_finished",
        "actor": "voss"
      }
    },
    {
      "id": "beat_6",
      "narrative_purpose": "Climax/Cliffhanger: The elevator doors open wide.",
      "target_start_second": 42.0,
      "actions": [
        {
          "actor": "voss",
          "action": "approach",
          "target": "floor_3_hallway"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "I'm seeing a floor labeled 'The Void'. This is a major citation. A massive one!"
        },
        {
          "actor": "ellis",
          "action": "react",
          "text": "Ooh, looks cozy! Very minimalist! I might move in!"
        },
        {
          "actor": "mara",
          "action": "sigh",
          "text": "I'm really not getting overtime for fixing the fabric of space-time."
        }
      ],
      "camera_intent": {
        "type": "cliffhanger_hold",
        "subject": "voss"
      },
      "completion_condition": {
        "type": "dialogue_finished",
        "actor": "mara"
      }
    }
  ],
  "payoff": "Voss begins writing a massive fine as the elevator begins to suck the hallway into a different dimension.",
  "persistent_changes": [],
  "notes": null
}
